200	Future<String> _doctorText() async {
201	  try {
202	    final BufferLogger logger = BufferLogger();
203	
204	    await context.run<bool>(
205	      body: () => doctor.diagnose(verbose: true),
206	      overrides: <Type, Generator>{
207	        Logger: () => logger,
208	      },
209	    );
210	
211	    return logger.statusText;
212	  } catch (error, trace) {
213	    return 'encountered exception: $error\n\n${trace.toString().trim()}\n';
214	  }
215	}
