20	void main() {
21	  group('runner', () {
22	    setUp(() {
23	      runner.crashFileSystem = MemoryFileSystem();
24	      // Instead of exiting with dart:io exit(), this causes an exception to
25	      // be thrown, which we catch with the onError callback in the zone below.
26	      io.setExitFunctionForTests((int _) { throw 'test exit';});
27	      Cache.disableLocking();
28	    });
29	
30	    tearDown(() {
31	      runner.crashFileSystem = const LocalFileSystem();
32	      io.restoreExitFunction();
33	      Cache.enableLocking();
34	    });
35	
36	    testUsingContext('error handling', () async {
37	      final Completer<void> completer = Completer<void>();
38	      // runner.run() asynchronously calls the exit function set above, so we
39	      // catch it in a zone.
40	      unawaited(runZoned<Future<void>>(
41	        () {
42	          unawaited(runner.run(
43	            <String>['test'],
44	            <FlutterCommand>[
45	              CrashingFlutterCommand(),
46	            ],
47	            // This flutterVersion disables crash reporting.
48	            flutterVersion: '[user-branch]/',
49	            reportCrashes: true,
50	          ));
51	          return null;
52	        },
53	        onError: (Object error) {
54	          expect(error, 'test exit');
55	          completer.complete();
56	        },
57	      ));
58	      await completer.future;
59	
60	      // This is the main check of this test.
61	      //
62	      // We are checking that, even though crash reporting failed with an
63	      // exception on the first attempt, the second attempt tries to report the
64	      // *original* crash, and not the crash from the first crash report
65	      // attempt.
66	      final CrashingUsage crashingUsage = flutterUsage as CrashingUsage;
67	      expect(crashingUsage.sentException, 'runCommand');
68	    }, overrides: <Type, Generator>{
69	      Platform: () => FakePlatform(environment: <String, String>{
70	        'FLUTTER_ANALYTICS_LOG_FILE': 'test',
71	        'FLUTTER_ROOT': '/',
72	      }),
73	      FileSystem: () => MemoryFileSystem(),
74	      ProcessManager: () => FakeProcessManager.any(),
75	      Usage: () => CrashingUsage(),
76	    });
77	  });
78	}
